body:
The following test fails when async copy is used. using NVFuserTestParaBool = NVFuserFixtureParamTest<bool>; TEST_P(NVFuserTestParaBool, FusionCpAsyncRace) {   NVFUSER_TEST_CUDA_ARCH_GUARD(8, 0);   Fusion fusion;   FusionGuard fg(&fusion);   int m = 64, n = 96;    // Use the parameterized value for use_async   const bool use_async = GetParam();   TensorView* tv0 = makeContigTensor(2);   TensorView* tv1 = makeContigTensor(1);   fusion.addInput(tv0);   fusion.addInput(tv1);    // copy tv0 to shared memory tv2   auto tv2 = set(tv0);   tv2->setMemoryType(MemoryType::Shared);   if (use_async) {     tv2->definition()->as<LoadStoreOp>()->setOpType(LoadStoreOpType::CpAsync);     tv2->definition()->as<LoadStoreOp>()->setCacheOp(CacheOp::Unspecified);   }    // copy tv1 to shared memory tv3   auto tv3 = set(tv1);   tv3->setMemoryType(MemoryType::Shared);   if (use_async) {     tv3->definition()->as<LoadStoreOp>()->setOpType(LoadStoreOpType::CpAsync);     tv3->definition()->as<LoadStoreOp>()->setCacheOp(CacheOp::Unspecified);    }    auto tv4 = broadcast(tv3, {true, false});   auto tv5 = add(tv2, tv4);   fusion.addOutput(tv5);    //[I0, I1] --> [I0/2, 2, 96]   for (auto tv : {tv0, tv2, tv4, tv5}) {     tv->split(0, 2);     tv->axis(-1)->parallelize(ParallelType::TIDx);         tv->axis(-2)->parallelize(ParallelType::TIDy);       }     //[I1]   for (auto tv : {tv1, tv3}) {     tv->axis(-1)->parallelize(ParallelType::TIDx);   }    inlineMost();    auto options = at::TensorOptions().dtype(at::kFloat).device(at::kCUDA, 0);   at::Tensor t0 = at::randn({m, n}, options);   at::Tensor t1 = at::randn({n}, options);    KernelExecutor ke;   ke.compile(&fusion, {t0, t1});   auto cg_outputs = ke.run({t0, t1});   testValidate(&fusion, cg_outputs, {t0, t1}, __LINE__, __FILE__); } INSTANTIATE_TEST_SUITE_P(     ,     NVFuserTestParaBool,     ::testing::Values(true, false));  The fusion_ir is: Inputs:   T0_g_float[ iS10{( ceilDiv(i0, 2) )}, ithreadIdx.y11{2}, ithreadIdx.x1{i2} ]   T1_g_float[ ithreadIdx.x2{i3} ] Outputs:   T5_g_float[ iS16{( ceilDiv(i0, 2) )}, ithreadIdx.y17{2}, ithreadIdx.x9{i2} ] ca_pos( 3 ) produce_pos( 3 )  %kernel_math { T2_s_float[ iS12{( ceilDiv(i0, 2) )}, ithreadIdx.y13{2}, ithreadIdx.x4{i2} ] ca_pos( 3 )    = CpAsync( T0_g_float[ iS10{( ceilDiv(i0, 2) )}, ithreadIdx.y11{2}, ithreadIdx.x1{i2} ] ) T3_s_float[ ithreadIdx.x5{i3} ] ca_pos( 1 )    = CpAsync( T1_g_float[ ithreadIdx.x2{i3} ] ) T4_l_float[ bS14{1}, bthreadIdx.y15{2}, ithreadIdx.x7{i3} ] ca_pos( 3 ) produce_pos( 3 )    = broadcast( T3_s_float[ ithreadIdx.x5{i3} ] ca_pos( 1 ) ) T5_g_float[ iS16{( ceilDiv(i0, 2) )}, ithreadIdx.y17{2}, ithreadIdx.x9{i2} ] ca_pos( 3 ) produce_pos( 3 )    = T2_s_float[ iS12{( ceilDiv(i0, 2) )}, ithreadIdx.y13{2}, ithreadIdx.x4{i2} ] ca_pos( 3 )    + T4_l_float[ bS14{1}, bthreadIdx.y15{2}, ithreadIdx.x7{i3} ] ca_pos( 3 ) produce_pos( 3 ); } // %kernel_math   The generated kernel for expr T3_s_float[ ithreadIdx.x5{i3} ] ca_pos( 1 ) = CpAsync( T1_g_float[ ithreadIdx.x2{i3} ] ) is: b9 = ((nvfuser_index_t)threadIdx.y) == 0LL;     asm volatile(       "{
"       "  .reg .pred p0; 
"       "  setp.ne.b32 p0, %3, 0;
"       "  cp.async.ca.shared.global [%0], [%1], %2, p0;
"       "}
"       :       :"r"((uint32_t)(i3)),        "l"(ptr1),        "n"(4LL),        "r"((uint32_t)((!b9)))     );     float T4[1LL];     asm volatile("cp.async.wait_all;
");     __syncthreads();  This is wrong, becuase threads with threadIdx.y != 0  will write 0 to shared memory which pollutes the correct value. The correct one should be:     if(b9){       asm volatile(         "{
"         "  .reg .pred p0; 
"         "  setp.ne.b32 p0, %3, 0;
"         "  cp.async.ca.shared.global [%0], [%1], %2, p0;
"         "}
"         :         :"r"((uint32_t)(i3)),          "l"(ptr1),          "n"(4LL),          "r"((uint32_t)((!b9)))       );     }

Originally found in CombinedSchedulerTest.LayerNormBackward/dtype_double_batch_216_hidden_96 using NVFUSER_DUMP=scheduler_params,cuda_to_file NVFUSER_ENABLE=kernel_debug PYTORCH_NO_CUDA_MEMORY_CACHING=1 compute-sanitizer --tool racecheck --racecheck-detect-level info  ./nvfuser_tests --gtest_filter='CombinedSchedulerTest.LayerNormBackward/dtype_double_batch_216_hidden_96'  Can be reproduced with a simple fusion: using NVFuserTestInlinedCpAsyncBool = NVFuserFixtureParamTest<bool>; TEST_P(NVFuserTestInlinedCpAsyncBool, FusionCpAsyncRaceBcastInlined) {   NVFUSER_TEST_CUDA_ARCH_GUARD(8, 0);   Fusion fusion;   FusionGuard fg(&fusion);   int m = 64, n = 96;    // Use the parameterized value for use_async   const bool inlined_cp_async = GetParam();   TensorView* tv0 = makeContigTensor(2);   TensorView* tv1 = makeContigTensor(1);   fusion.addInput(tv0);   fusion.addInput(tv1);    // copy tv0 to shared memory tv2   auto tv2 = set(tv0);   tv2->setMemoryType(MemoryType::Shared);   tv2->definition()->as<LoadStoreOp>()->setOpType(LoadStoreOpType::CpAsync);   tv2->definition()->as<LoadStoreOp>()->setCacheOp(CacheOp::Unspecified);    // copy tv1 to shared memory tv3   auto tv3 = set(tv1);   tv3->setMemoryType(MemoryType::Shared);   tv3->definition()->as<LoadStoreOp>()->setOpType(LoadStoreOpType::CpAsync);   tv3->definition()->as<LoadStoreOp>()->setCacheOp(CacheOp::Unspecified);     auto tv4 = broadcast(tv3, {true, false});   auto tv5 = add(tv2, tv4);   fusion.addOutput(tv5);    // No Race if TIDy is not used   // for (auto tv : {tv0, tv2, tv4, tv5}) {   //   tv->split(0, 5);   //   tv->axis(1)->parallelize(ParallelType::BIDy);       // }     for (auto tv : {tv0, tv2, tv4, tv5}) {     tv->split(0, 2);     tv->split(0, 5);     tv->axis(2)->parallelize(ParallelType::TIDy);         tv->axis(1)->parallelize(ParallelType::BIDy);       }    for (auto tv : {tv0, tv1, tv2, tv3, tv4, tv5}) {     tv->split(-1, 1, false);     tv->axis(-1)->parallelize(ParallelType::TIDx);     tv->axis(-2)->parallelize(ParallelType::Unswitch);   }    fusion.printMath();   // No Race if all tvs are inlined   if(inlined_cp_async){     inlineMost();   }else{     inlineMost(std::vector<TensorView*>{tv2, tv4, tv5});   }    auto options = at::TensorOptions().dtype(at::kFloat).device(at::kCUDA, 0);   at::Tensor t0 = at::randn({m, n}, options);   at::Tensor t1 = at::randn({n}, options);    KernelExecutor ke;   ke.compile(&fusion, {t0, t1});   auto cg_outputs = ke.run({t0, t1});   testValidate(&fusion, cg_outputs, {t0, t1}, __LINE__, __FILE__); }  INSTANTIATE_TEST_SUITE_P(     ,     NVFuserTestInlinedCpAsyncBool,     ::testing::Values(false, true));  If run this fusion using current main branch with NVFUSER_DUMP=cuda_to_file NVFUSER_ENABLE=kernel_debug compute-sanitizer --tool racecheck ./nvfuser_tests --gtest_filter=*FusionCpAsyncRaceBcastInlined/0 will get: ========= Error: Race reported between Write access at <unnamed>::nvfuser_none_f0_c0_r0_g0(<unnamed>::Tensor<float, (int)2, (int)2>, <unnamed>::Tensor<float, (int)1, (int)1>, <unnamed>::Tensor<float, (int)2, (int)2>)+0x2be0 in /opt/pytorch/nvfuser/build/__tmp_kernel_none_f0_c0_r0_g0.cu:10883 =========     and Read access at <unnamed>::nvfuser_none_f0_c0_r0_g0(<unnamed>::Tensor<float, (int)2, (int)2>, <unnamed>::Tensor<float, (int)1, (int)1>, <unnamed>::Tensor<float, (int)2, (int)2>)+0x34b0 in /opt/pytorch/nvfuser/build/__tmp_kernel_none_f0_c0_r0_g0.cu:10907 [1920 hazards]  The generated kernel is __global__ void nvfuser_none_f0_c0_r0_g0(Tensor<float, 2, 2> T0, Tensor<float, 1, 1> T1, Tensor<float, 2, 2> T5) {   alignas(16) extern __shared__ char array[];   const unsigned smem_offset = 0;   nvfuser_index_t i0;   i0 = ceilDiv((ceilDiv(T0.logical_size[0LL], 2LL)), 5LL);   nvfuser_index_t i1;   i1 = 4LL * ((nvfuser_index_t)threadIdx.x);   nvfuser_index_t i2;   i2 = T0.logical_size[1LL] * ((nvfuser_index_t)threadIdx.y);   nvfuser_index_t i3;   i3 = (2LL * T0.logical_size[1LL]) * ((nvfuser_index_t)blockIdx.y);   float* ptr4;   ptr4 = ((T0.data + ((nvfuser_index_t)threadIdx.x)) + i2) + i3;   nvfuser_index_t i5;   i5 = 10LL * T0.logical_size[1LL];   float* T3 = reinterpret_cast<float*>(array + smem_offset + ((((2LL * T0.logical_size[1LL]) * 4LL) + 15LL) & -16LL));   float* T2 = reinterpret_cast<float*>(array + smem_offset + 0LL);   unsigned i6;   i6 = (toSmem(T2) + i1) + ((4LL * T0.logical_size[1LL]) * ((nvfuser_index_t)threadIdx.y));   nvfuser_index_t i7;   i7 = ((nvfuser_index_t)threadIdx.x) + i2;   nvfuser_index_t i8;   i8 = i7 + i3;   bool b9;   b9 = ((nvfuser_index_t)threadIdx.y) == 0LL;   nvfuser_index_t i10;   i10 = ((nvfuser_index_t)threadIdx.y) + (2LL * ((nvfuser_index_t)blockIdx.y));   if (b9) {     asm volatile(       "{
"       "  .reg .pred p0; 
"       "  setp.ne.b32 p0, %3, 0;
"       "  cp.async.ca.shared.global [%0], [%1], %2, p0;
"       "}
"       :       :"r"((uint32_t)((toSmem(T3) + i1))),        "l"((T1.data + ((nvfuser_index_t)threadIdx.x))),        "n"(4LL),        "r"((uint32_t)((!b9)))     );   }   __syncthreads();   #pragma unroll 1   for(nvfuser_index_t i11 = 0LL; i11 < i0; ++i11) {     nvfuser_index_t i12;     i12 = i5 * i11;     if (((i10 + (10LL * i11)) < T0.logical_size[0LL])) {       asm volatile(         "{
"         "  .reg .pred p0; 
"         "  setp.ne.b32 p0, %3, 0;
"         "  cp.async.ca.shared.global [%0], [%1], %2, p0;
"         "}
"         :         :"r"((uint32_t)(i6)),          "l"((ptr4 + i12)),          "n"(4LL),          "n"((uint32_t)(false))       );       float T4[1LL];       asm volatile("cp.async.wait_all;
");       T4[0LL]          = T3[((nvfuser_index_t)threadIdx.x)];       T5[(i8 + i12)]         = T2[i7]         + T4[0LL];     }   } }  Race happens at the read & write of T3

Test DistributedTransformerTest.Backward/__bfloat has bool type tensor, when shared memory persistent is used with async copy, it triggers a bug. A mini-reproduce is as follows: TEST_F(NVFuserTest, CpAsyncDataTypeBool) {   Fusion fusion;   FusionGuard fg(&fusion);   auto dtype = DataType::Bool;   int m = 33, n = 128;   auto tv0 = makeContigConcreteTensor({m, n}, dtype);   fusion.addInput(tv0);   auto tv1 = set(tv0);   tv1->setMemoryType(MemoryType::Shared);   tv1->definition()->as<LoadStoreOp>()->setOpType(       LoadStoreOpType::CpAsync);   tv1->definition()->as<LoadStoreOp>()->setCacheOp(CacheOp::Unspecified);   auto tv2 = castOp(DataType::Int32, tv1);   fusion.addOutput(tv2);      for(auto tv : {tv0, tv1, tv2}){     tv->split(1, 4);   }   for(auto tv : {tv0, tv1, tv2}){     tv->axis(0)->parallelize(ParallelType::BIDx);     tv->axis(1)->parallelize(ParallelType::TIDx);   }   tv1->axis(2)->parallelize(ParallelType::Vectorize);    inlineMost();    auto at_dtype = data_type_to_aten(dtype);   auto options = at::TensorOptions().dtype(at_dtype).device(at::kCUDA, 0);   // randn deosn't support bool type   at::Tensor t0 = at::ones({m, n}, options);    FusionExecutor fe;    // requires ampere+ GPU   if (!deviceMajorMinorCheck(8)) {     ASSERT_THAT(         [&]() { fe.compileFusion(&fusion, {t0}); },         testing::ThrowsMessage<nvfuser::nvfError>(testing::HasSubstr(             "Reason: LoadStoreOpType::CpAsync requires Ampere")));     GTEST_SKIP() << "skipping tests on pre-AMPERE GPUs";   } else {     fe.compileFusion(&fusion, {t0});   }   fe.compileFusion(&fusion, {t0});   auto cg_outputs = fe.runFusion({t0});    testValidate(&fusion, cg_outputs, {t0}, __LINE__, __FILE__); }  The generated code is: __global__ void nvfuser_none_f0_c0_r0_g0(Tensor<bool, 2, 2> T0, Tensor<int, 2, 2> T2) {   alignas(16) extern __shared__ char array[];   const unsigned smem_offset = 0;   NVFUSER_DEFINE_MAGIC_ZERO;   nvfuser_index_t i0;   i0 = 4LL * ((nvfuser_index_t)threadIdx.x);   nvfuser_index_t i1;   i1 = 128LL * ((nvfuser_index_t)blockIdx.x);   nvfuser_index_t i2;   i2 = i0 + i1;   bool b3;   b3 = (3LL + i0) < 128LL;   bool* T1 = reinterpret_cast<bool*>(array + smem_offset + 0LL);   asm volatile(     "{
"     "  .reg .pred p0; 
"     "  setp.ne.b32 p0, %0, 0;
"     "  .reg .pred p1; 
"     "  setp.ne.b32 p1, %1, 0;
"     "  .reg .pred p2; 
"     "  setp.ne.b32 p2, %3, 0;
"     "  cp.async.ca.shared.global [%0], [%1], %2, p0;
"     "}
"     :     :"r"((uint32_t)((uint32_t)((toSmem(T1) + i0)))),      "l"((uint32_t)(((T0.data + i0) + i1))),      "n"(4LL),      "r"((uint32_t)((!b3)))   );   asm volatile("cp.async.wait_all;
");   #pragma unroll   for(nvfuser_index_t i4 = 0LL; i4 < 4LL; ++i4) {     if (b3) {       T2[(i2 + (i4 + nvfuser_zero))]          = (int32_t)(T1[(i0 + i4)]);     }   }   NVFUSER_UPDATE_MAGIC_ZERO; }  Durint lowering, the pointer to bool is processed as bool and being converted to uint32_t.
